import React from "react";
import Swal from 'sweetalert2'
import "./Contacts.css";

const Torneo = () => {

  const onSubmit = async (event) => {
          event.preventDefault();
          const formData = new FormData(event.target);

          formData.append("access_key", "8f3cb066-6bc3-4797-ad5c-2c7ac02c44ea");

          const object = Object.fromEntries(formData);
          const json = JSON.stringify(object);

          const res = await fetch("https://api.web3forms.com/submit", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Accept: "application/json"
            },
            body: json
          }).then((res) => res.json());

          if (res.success) {
              Swal.fire({
                  title: 'Success!',
                  text: 'Message sent successfully',
                  icon: 'success',
                })
          }
          else{
            Swal.fire({
                  title: 'Error!',
                  text: 'Error',
                  icon: 'Error',
                })
          }
        };

  return (
    <div className="contacts">

      <div className="contacts-form">

        <form onSubmit={onSubmit}>

          <h1 className="contact-title">Torneo Seriana Cobras</h1>

          <p style={{textAlign:"center", marginBottom:"30px"}}>
            Inserisci qui la descrizione del torneo, regolamento e informazioni.
          </p>

          {/* SEZIONE 1 */}
          <h2 style={{textAlign:"center", marginTop:"50px", marginBottom:"50px"}}>Informazioni squadra</h2>

          <div className="input-box">
            <label>Nome della squadra</label>
            <input type="text" className="field" required />
          </div>

          <div className="input-box">
            <label>Nome e cognome capitano</label>
            <input type="text" className="field" required />
          </div>

          <div className="input-box">
            <label>Data di nascita capitano</label>
            <input type="date" className="field" required />
          </div>

          <div className="input-box">
            <label>Email</label>
            <input type="email" className="field" required />
          </div>

          <div className="input-box">
            <label>Numero di telefono</label>
            <input type="tel" className="field" required />
          </div>

          <div className="input-box">
            <label>Allega visita medica agonistica capitano</label>
            <input type="file" className="field" accept=".pdf,.jpg,.png" required />
          </div>

          <div className="input-box">
            <label>Note della squadra</label>
            <textarea className="field mess"></textarea>
          </div>


          {/* SEZIONE 2 */}
          <h2 style={{textAlign:"center", marginTop:"50px", marginBottom:"50px"}}>Giocatore 2</h2>

          <div className="input-box">
            <label>Nome e cognome giocatore 2</label>
            <input type="text" className="field" required />
          </div>

          <div className="input-box">
            <label>Data di nascita giocatore 2</label>
            <input type="date" className="field" required />
          </div>

          <div className="input-box">
            <label>Visita medica giocatore 2</label>
            <input type="file" className="field" accept=".pdf,.jpg,.png" required />
          </div>

          {/* SEZIONE 3 */}
          <h2 style={{textAlign:"center", marginTop:"50px", marginBottom:"50px"}}>Giocatore 3</h2>

          <div className="input-box">
            <label>Nome e cognome giocatore 3</label>
            <input type="text" className="field" required />
          </div>

          <div className="input-box">
            <label>Data di nascita giocatore 3</label>
            <input type="date" className="field" required />
          </div>

          <div className="input-box">
            <label>Visita medica giocatore 3</label>
            <input type="file" className="field" accept=".pdf,.jpg,.png" required />
          </div>

          <button type="submit">
            Invia iscrizione
          </button>

        </form>

      </div>

    </div>
  );
};

export default Torneo;
